from __future__ import annotations

import json
import re
from pathlib import Path

_CACHE_DIR = Path(__file__).resolve().parent.parent.parent / "tmp" / "008_A_Chinese_and_English_Vocabulary_in_the_Tie-chiu_Dialect" / "wikitext"
_OUT = Path(__file__).resolve().parent.parent.parent / "export" / "008_wikisource_page_map.csv"
_JSON_OUT = Path(__file__).resolve().parent.parent.parent / "export" / "008_wikisource_page_map.json"

TOTAL_FRAMES = 315

_RH_RE = re.compile(r"\{\{rh\|(\d+)(?:\|[^}]*)?\}\}")
_RH_EMPTY_RE = re.compile(r"\{\{rh\|\|")
_PAGELIST_HREF_RE = re.compile(r'href="[^"]*?djvu/(\d+)"[^>]*>([^<]+)<')

def _section_label(frame: int) -> str:
    if frame <= 16:
        return "front_matter"
    if 17 <= frame <= 190:
        return "dictionary"
    if 191 <= frame <= 253:
        return "radical_index"
    return "back_matter"

def parse_pagelist_html(html: str) -> dict[int, str]:
    frames: dict[int, str] = {}
    for m in _PAGELIST_HREF_RE.finditer(html):
        frame = int(m.group(1))
        label = m.group(2).strip()
        frames[frame] = label
    return frames

def load_rh_data() -> dict[int, int | None]:
    files = sorted(_CACHE_DIR.glob("p*.wikitext"), key=lambda f: int(f.stem[1:]))
    rh: dict[int, int | None] = {}
    for f in files:
        ws_page = int(f.stem[1:])
        content = f.read_text(encoding="utf-8")
        m = _RH_RE.search(content)
        rh_empty = bool(_RH_EMPTY_RE.search(content))
        if m:
            rh[ws_page] = int(m.group(1))
        elif rh_empty:
            rh[ws_page] = None
    return rh

